// MCP tools backed by the same cores as the batch-44 browser tools (src/tools_core44.js, generated by gen_tools_core.py).
// Pure functions — no D1/R2 access. Each returns an MCP tool result.
import { MGDPlanCore, MGDWordSearch, MGDCrossword, MGDBingo, MGDUsername, MGDGantt, MGDCalendar, MGDSchedule, MGDTimeline, MGDOrg, MGDVenn, MGDPie } from "./tools_core44.js";

const T = "https://madegooddesigns.com/tools";
const ok = (text) => ({ content: [{ type: "text", text }] });
const err = (text) => ({ content: [{ type: "text", text }], isError: true });
const str = (x, max) => (typeof x === "string" ? x : x == null ? "" : String(x)).slice(0, max);
const int = (x, d, lo, hi) => { const n = parseInt(x, 10); return Number.isFinite(n) ? Math.max(lo, Math.min(hi, n)) : d; };
const RO = (title) => ({ title, readOnlyHint: true, destructiveHint: false, openWorldHint: false });
const list = (x, max, n) => (Array.isArray(x) ? x : typeof x === "string" ? x.split(/\r?\n|,/) : []).map((s) => str(s, max).trim()).filter(Boolean).slice(0, n);
const svgBlock = (svg) => "```svg\n" + svg + "\n```";
const seedOf = (a) => (a.seed == null || a.seed === "" ? Math.floor(Math.random() * 1e9).toString(36).toUpperCase() : str(a.seed, 40));

const USER_STYLES = Object.keys(MGDUsername.styles);
const USER_PLATFORMS = Object.keys(MGDUsername.platforms);
