const NAMES = new Set(TOOL_DEFS.map((t) => t.name));
export function isTools44Tool(name) { return NAMES.has(name); }

export function callTools44Tool(name, a) {
  a = a || {};
  try {
    if (name === "make_word_search") return wordSearch(a);
    if (name === "make_crossword") return crossword(a);
    if (name === "make_bingo_cards") return bingo(a);
    if (name === "generate_usernames") return usernames(a);
    if (name === "schedule_gantt_chart") return gantt(a);
    if (name === "get_public_holidays") return holidays(a);
    if (name === "make_weekly_schedule") return schedule(a);
    if (name === "text_to_timeline") return timeline(a);
    if (name === "make_org_chart") return orgChart(a);
    if (name === "make_venn_diagram") return venn(a);
    if (name === "make_pie_chart") return pie(a);
  } catch (e) {
    return err("The tool failed: " + (e && e.message ? e.message : String(e)));
  }
  return err("Unknown tool: " + name);
}

const DIR_WORDS = MGDWordSearch.DIR_NAMES;

function wordSearch(a) {
  const words = list(a.words, 40, 80);
  if (words.length < 2) return err("Pass at least 2 words.");
  const opt = { words, difficulty: ["easy", "medium", "hard"].includes(a.difficulty) ? a.difficulty : "medium", shape: MGDWordSearch.SHAPES.includes(a.shape) ? a.shape : "rectangle",
    letterCase: a.lowercase ? "lower" : "upper", seed: seedOf(a) };
  if (a.size) { opt.rows = opt.cols = int(a.size, 15, 6, 30); } else opt.size = "auto";
  const r = MGDWordSearch.generate(opt);
  const grid = r.grid.map((row) => row.map((c) => c == null ? " " : c).join(" ")).join("\n");
  const key = r.placements.map((p) => `- ${p.display}: row ${p.row + 1}, column ${p.col + 1}, ${DIR_WORDS[p.dir]}`).join("\n");
  const skipped = r.skipped.length ? `\n\nNot placed: ${r.skipped.map((s) => `${s.word} (${s.reason})`).join("; ")}` : "";
  return ok(`Word search ${r.rows}×${r.cols} (${opt.difficulty}, ${r.shape}), ${r.placements.length} words, seed ${r.seed}.\n\n\`\`\`\n${grid}\n\`\`\`\n\nFind these words: ${r.placements.map((p) => p.display).join(", ")}${skipped}\n\nAnswer key (rows and columns count from 1 at the top left):\n${key}\n\nPrintable PDF with answer key, shapes and multiple versions: ${T}/word-search-maker/`);
}

function crossword(a) {
  let entries = Array.isArray(a.entries) ? a.entries.slice(0, 60).map((e) => ({ answer: str(e && e.answer, 40), clue: str(e && e.clue, 300) })).filter((e) => e.answer.trim()) : [];
  if (!entries.length && a.text) entries = MGDCrossword.parse(str(a.text, 20000)).slice(0, 60);
  if (entries.length < 2) return err("Pass at least 2 entries (answer + clue).");
  const r = MGDCrossword.generate({ entries, seed: seedOf(a), maxSize: int(a.max_size, 21, 8, 30) });
  if (r.entries.length < 2) return err("These words could not be joined into a crossword (they need to share letters). Add more words that share letters with them.");
  const num = {}; r.entries.forEach((e) => { num[e.row + "," + e.col] = e.number; });
  const grid = r.grid.map((row) => row.map((c) => (c == null ? "#" : c)).join(" ")).join("\n");
  const blank = r.grid.map((row, y) => row.map((c, x) => (c == null ? "##" : num[y + "," + x] != null ? String(num[y + "," + x]).padStart(2, " ") : " .")).join(" ")).join("\n");
  const clues = (arr) => arr.map((e) => `${e.number}. ${e.clue || "(no clue)"} ${e.enumeration}`).join("\n");
  const ans = r.entries.slice().sort((x, y) => x.number - y.number || (x.dir < y.dir ? -1 : 1)).map((e) => `${e.number} ${e.dir}: ${e.display}`).join(", ");
  const un = r.unplaced.length ? `\n\nCould not be joined (add words that share letters with them): ${r.unplaced.map((u) => u.answer).join(", ")}` : "";
  return ok(`Crossword ${r.rows}×${r.cols}, ${r.entries.length} words, ${r.intersections} crossings, seed ${r.seed}.\n\nBlank grid (## = black square, numbers = clue starts):\n\`\`\`\n${blank}\n\`\`\`\n\nACROSS\n${clues(r.across)}\n\nDOWN\n${clues(r.down)}${un}\n\nSolution grid:\n\`\`\`\n${grid}\n\`\`\`\nAnswers: ${ans}\n\nPrintable PDF, answer key and online solving: ${T}/crossword-maker/`);
}

function bingo(a) {
  const items = list(a.items, 60, 300);
  const mode = ["words", "75", "90", "range"].includes(a.mode) ? a.mode : items.length ? "words" : "75";
  const opt = { mode, items, size: [3, 4, 5].includes(+a.size) ? +a.size : 5, count: int(a.count, 4, 1, 30), free: a.free_space !== false, freeText: str(a.free_text, 20) || "FREE", seed: seedOf(a) };
  if (mode === "range") { opt.min = int(a.min, 1, -9999, 99999); opt.max = int(a.max, 50, -9999, 99999); }
  const r = MGDBingo.generate(opt);
  if (r.error) return err(r.error);
  const cell = (c) => (c == null ? " " : c.free ? "★ " + c.text : c.text).replace(/\|/g, "/");
  const cards = r.cards.map((c) => {
    const head = mode === "75" && r.cols === 5 ? "| B | I | N | G | O |" : "|" + " |".repeat(r.cols);
    return `Card ${c.number}\n${head}\n|${"---|".repeat(r.cols)}\n` + c.cells.map((row) => "| " + row.map(cell).join(" | ") + " |").join("\n");
  }).join("\n\n");
  const calls = r.calls.map((c) => (c.column ? c.column + "-" : "") + c.text).join(", ");
  const warn = r.warnings && r.warnings.length ? `\nNotes: ${r.warnings.join("; ")}` : "";
  return ok(`${r.count} unique ${mode === "words" ? "word" : mode === "range" ? "number" : mode + "-ball"} bingo cards (${r.rows}×${r.cols}), seed ${r.seed}.${warn}\n\n${cards}\n\nCaller list (shuffled): ${calls}\n\nPrintable PDF (up to 500 cards, 1/2/4 per page) with a caller sheet and on-screen caller: ${T}/bingo-card-generator/`);
}

function usernames(a) {
  const platform = USER_PLATFORMS.includes(a.platform) ? a.platform : "any", P = MGDUsername.platforms[platform];
  const out = [];
  if (a.check) {
    const name = str(a.check, 60), v = MGDUsername.validate(name, platform);
    out.push(v.ok ? `"${name}" fits ${P.label} rules (${v.length} characters; ${P.min}–${P.max} allowed).` :
      `"${name}" does not fit ${P.label}: ${v.errors.join("; ")}. Fixed version: ${MGDUsername.fix(name, platform)}`);
  }
  const style = USER_STYLES.includes(a.style) ? a.style : "cool";
  const r = MGDUsername.generate({ keyword: str(a.keyword, 40), style, platform, count: int(a.count, 20, 1, 50), seed: seedOf(a) });
  out.push(`${r.length} ${MGDUsername.styles[style].label.toLowerCase()} username ideas for ${P.label} (${P.min}–${P.max} characters, ${P.chars}):\n` + r.map((u) => `- ${u.name}`).join("\n"));
  out.push(`These follow ${P.label}'s format rules but availability isn't checked — try them on the platform. More styles and a checker: ${T}/username-generator/`);
  return ok(out.join("\n\n"));
}

function gantt(a) {
  let tasks;
  if (Array.isArray(a.tasks) && a.tasks.length) {
    tasks = a.tasks.slice(0, 150).map((t, i) => ({ id: int(t.id, i + 1, 0, 1e6), name: str(t.name, 120), type: ["task", "milestone", "group"].includes(t.type) ? t.type : "task",
      start: str(t.start, 10), dur: t.type === "milestone" ? 0 : Math.max(0, Number(t.duration != null ? t.duration : t.dur) || (t.type === "group" ? 0 : 1)), deps: str(t.deps, 200),
      progress: Math.max(0, Math.min(100, Number(t.progress) || 0)), owner: str(t.owner, 80) }));
  } else if (a.csv) tasks = MGDGantt.parseCSV(str(a.csv, 100000)).slice(0, 150);
  else return err("Pass tasks (or csv).");
  const workdays = a.workdays !== false;
  const sc = MGDGantt.schedule(tasks, { workdays });
  const iso = MGDPlanCore.iso;
  const rows = sc.tasks.map((t) => `| ${t.id} | ${str(t.name, 60).replace(/\|/g, "/")} | ${t.type} | ${t.s != null ? iso(t.s) : "—"} | ${t.e != null ? iso(t.e) : "—"} | ${t.days != null ? t.days : ""} | ${t.slack != null ? t.slack : ""} | ${t.crit ? "yes" : ""}${t.err ? " ⚠ " + t.err : ""} |`).join("\n");
  const crit = sc.tasks.filter((t) => t.crit && t.type !== "group").map((t) => t.name);
  const errs = sc.errors && sc.errors.length ? `\nProblems: ${sc.errors.join("; ")}` : "";
  let out = `Project ${sc.start != null ? iso(sc.start) : "?"} → ${sc.end != null ? iso(sc.end) : "?"} (${workdays ? "work days, Mon–Fri" : "calendar days"}), ${sc.tasks.length} rows.${errs}\nCritical path: ${crit.join(" → ") || "—"}\n\n| ID | Task | Type | Start | Finish | ${workdays ? "Work days" : "Days"} | Slack | Critical |\n|---|---|---|---|---|---|---|---|\n${rows}`;
  if (a.svg !== false) out += `\n\n${svgBlock(MGDGantt.svg(tasks, { workdays }).svg)}`;
  return ok(out + `\n\nDrag bars, change the timescale and export PNG/PDF/CSV: ${T}/gantt-chart-maker/`);
}

function holidays(a) {
  const year = int(a.year, new Date().getUTCFullYear(), 1900, 2200);
  const country = COUNTRIES.includes(String(a.country || "").toUpperCase()) ? String(a.country).toUpperCase() : null;
  if (!country) return err("country must be one of " + COUNTRIES.join(", ") + ".");
  const h = MGDCalendar.holidays(year, country, { observances: !!a.observances }).slice().sort((x, y) => x.n - y.n);
  const label = { US: "United States (federal)", UK: "United Kingdom (England & Wales bank holidays)", CA: "Canada (national statutory)", AU: "Australia (national)" }[country];
  const rows = h.map((d) => { const y = MGDPlanCore.ymd(d.n); return `| ${MGDPlanCore.iso(d.n)} | ${MGDPlanCore.DOW[y.dow]} | ${d.name} | ${d.kind === "public" ? "public holiday" : d.kind} |`; }).join("\n");
  const extra = h.filter((d) => /\((observed|substitute day)\)$/.test(d.name)).length, pub = h.filter((d) => d.kind === "public").length - extra;
  return ok(`${label} holidays in ${year}: ${pub} public holidays${extra ? ` (plus ${extra} observed/substitute weekday${extra > 1 ? "s" : ""})` : ""}.\n\n| Date | Day | Holiday | Type |\n|---|---|---|---|\n${rows}\n\nRegional/state holidays are not included. Printable ${year} calendar with these holidays: ${T}/calendar-maker/`);
}

function schedule(a) {
  const text = str(a.text, 20000);
  if (!text.trim()) return err("Pass schedule lines, e.g. 'Mon Wed Fri 9-10:15 Biology @ Room 204'.");
  const p = MGDSchedule.parseText(text);
  if (!p.events.length) return err("No events could be read." + (p.errors.length ? " " + p.errors.join("; ") : ""));
  const ev = p.events.slice(0, 200);
  const rows = ev.map((e) => `| ${MGDSchedule.daysText(e.days)} | ${MGDPlanCore.fmtTime(e.start)}–${MGDPlanCore.fmtTime(e.end)} | ${str(e.title, 80)} | ${e.location || ""} | ${e.person || ""} |`).join("\n");
  let out = `${ev.length} weekly events.${p.errors.length ? `\nLines not understood: ${p.errors.join("; ")}` : ""}\n\n| Days | Time | Event | Where | Who |\n|---|---|---|---|---|\n${rows}\n\n${svgBlock(MGDSchedule.svg(ev, {}).svg)}`;
  if (a.ics) {
    const from = /^\d{4}-\d{2}-\d{2}$/.test(str(a.ics_start, 10)) ? MGDPlanCore.parseDate(a.ics_start) : undefined;
    out += `\n\nSave this as schedule.ics and import it into Google Calendar, Apple Calendar or Outlook:\n\`\`\`\n${MGDSchedule.toICS(ev, { from, weeks: int(a.ics_weeks, 15, 1, 52) })}\n\`\`\``;
  }
  return ok(out + `\n\nPrintable PDF (Letter/A4), staff-rota view and PNG: ${T}/schedule-maker/`);
}

function timeline(a) {
  const model = { title: str(a.title, 120) };
  if (Array.isArray(a.events) && a.events.length) model.events = a.events.slice(0, 200).map((e) => ({ date: str(e.date, 40), end: e.end ? str(e.end, 40) : undefined, title: str(e.title, 120), desc: str(e.desc, 300) }));
  else if (a.text) model.text = str(a.text, 30000);
  else return err("Pass text or events.");
  const r = MGDTimeline.render(Object.assign(model, { orientation: a.orientation === "vertical" ? "vertical" : "horizontal", scale: a.scale === "even" ? "even" : "proportional" }));
  const w = r.warnings && r.warnings.length ? `\nNotes: ${r.warnings.join("; ")}` : "";
  return ok(`Timeline: ${r.events.length} events, ${Math.round(r.width)}×${Math.round(r.height)} px.${w}\n\n${svgBlock(r.svg)}\n\nEdit, add eras and export PNG/SVG/PDF: ${T}/timeline-maker/`);
}

function orgChart(a) {
  const opt = { direction: a.direction === "LR" ? "LR" : "TB", headcount: !!a.headcount, colorBy: ["dept", "level", "none"].includes(a.color_by) ? a.color_by : "dept", title: str(a.title, 120) };
  if (a.csv) opt.csv = str(a.csv, 100000); else if (a.text) opt.text = str(a.text, 100000); else return err("Pass text (indented list) or csv.");
  const r = MGDOrg.render(opt);
  if (!r.nodes || !r.nodes.length) return err("No people could be read from that input.");
  const w = r.warnings && r.warnings.length ? `\nNotes: ${r.warnings.join("; ")}` : "";
  return ok(`Org chart: ${r.nodes.length} people, ${Math.round(r.width)}×${Math.round(r.height)} px.${w}\n\n${svgBlock(r.svg)}\n\nDrag people to new managers, add photos and export PNG/SVG/PDF/CSV: ${T}/org-chart-maker/`);
}

function venn(a) {
  const sets = (Array.isArray(a.sets) ? a.sets : []).slice(0, 4).map((s) => ({ name: str(s && s.name, 60) || "Set", items: s && s.items ? list(s.items, 120, 2000) : undefined }));
  if (sets.length < 2) return err("Pass 2–4 sets.");
  const useItems = sets.some((s) => s.items && s.items.length);
  const opt = { sets, mode: useItems ? "items" : "text", title: str(a.title, 120), proportional: !!a.proportional && sets.length === 2 };
  if (a.regions && typeof a.regions === "object") { opt.regions = {}; Object.keys(a.regions).slice(0, 15).forEach((k) => { opt.regions[k.toUpperCase()] = str(a.regions[k], 300); }); if (!useItems) opt.mode = "text"; }
  const r = MGDVenn.render(opt);
  const names = sets.map((s, i) => `${"ABCD"[i]} = ${s.name}`).join(", ");
  const rows = r.regions.map((g) => `- ${g.label}${useItems ? ` (${g.count})` : ""}: ${useItems ? (g.items.length ? g.items.slice(0, 50).join(", ") + (g.items.length > 50 ? ", …" : "") : "—") : g.text || "—"}`).join("\n");
  return ok(`Venn diagram, ${sets.length} sets (${names}).\n\n${rows}\n\n${svgBlock(r.svg)}\n\nRecolour, resize and export PNG/SVG/PDF or the overlap CSV: ${T}/venn-diagram-maker/`);
}

function pie(a) {
  let items = Array.isArray(a.items) && a.items.length ? a.items.slice(0, 100).map((i) => ({ label: str(i.label, 80), value: Number(i.value), color: i.color ? str(i.color, 9) : "" })).filter((i) => Number.isFinite(i.value)) :
    a.data ? MGDPie.parse(str(a.data, 50000)).slice(0, 100) : [];
  if (!items.length) return err("Pass data ('Label, value' lines) or items.");
  const opt = { type: a.type === "donut" ? "donut" : "pie", half: !!a.half, title: str(a.title, 120), labels: a.labels || "label-percent", decimals: int(a.decimals, 0, 0, 2),
    sort: ["none", "desc", "asc"].includes(a.sort) ? a.sort : "none", prefix: str(a.prefix, 6), suffix: str(a.suffix, 10) };
  if (a.other_below) opt.otherBelow = Math.max(0, Math.min(50, Number(a.other_below) || 0));
  const r = MGDPie.svg(items, opt);
  const rows = r.slices.map((s) => `| ${s.label} | ${s.valueText} | ${s.pctText} | ${s.color} |`).join("\n");
  const dropped = r.dropped && r.dropped.length ? `\nIgnored (zero or negative): ${r.dropped.map((d) => d.label).join(", ")}` : "";
  return ok(`${opt.half ? "Half " : ""}${opt.type} chart, ${r.slices.length} slices, total ${r.totalText}.${dropped}\n\n| Slice | Value | Share | Colour |\n|---|---|---|---|\n${rows}\n\n${svgBlock(r.svg)}\n\nPNG/PDF export, per-slice colours and pull-out slices: ${T}/pie-chart-maker/`);
}
